<template><view v-if="modelValue" class="overlay" @click="close"><view class="sheet" @click.stop><view class="sheet-header"><button class="close" aria-label="关闭评论" @click="close"><CrowIcon name="cross"/></button><text>写评论</text><button class="publish" @click="publish">发表</button></view><textarea v-model="draft" placeholder="说两句吧" :focus="true" maxlength="1000"/></view></view></template>
<script setup>import {ref,watch} from 'vue';import CrowIcon from './CrowIcon.vue';const props=defineProps({modelValue:Boolean,postId:[String,Number]});const emit=defineEmits(['update:modelValue']);const draft=ref('');watch(()=>props.modelValue,v=>{if(v)draft.value=uni.getStorageSync('crowlook:draft:'+props.postId)||''});const close=()=>{uni.setStorageSync('crowlook:draft:'+props.postId,draft.value);emit('update:modelValue',false)};const publish=()=>{if(!draft.value.trim()){uni.showToast({title:'评论内容不能为空',icon:'none'});return}uni.setStorageSync('crowlook:draft:'+props.postId,draft.value);uni.showModal({title:'草稿已保存',content:'本地预览尚未连接评论发布服务，内容没有发送。',showCancel:false})}</script>
<style scoped>.overlay{position:fixed;inset:0;background:linear-gradient(to bottom,transparent 116rpx,rgba(0,0,0,.72) 116rpx);z-index:80}.sheet{position:absolute;bottom:0;left:0;right:0;height:67%;background:#fff;border-radius:30rpx 30rpx 0 0;padding:30rpx 30rpx}.sheet-header{display:flex;align-items:center;justify-content:center;position:relative;height:54rpx;font-size:16px;font-weight:700}.close{position:absolute;left:10rpx;background:none;padding:0;line-height:1;font-size:24px}.publish{position:absolute;right:0;background:#07c160;color:#fff;font-size:14px;line-height:56rpx;border-radius:40rpx;padding:0 28rpx;font-weight:400}.sheet textarea{margin:38rpx 14rpx;width:calc(100% - 28rpx);height:75%;font-size:16px;line-height:1.6}</style>
